//! D1 reference oracles for R18.4: Custom DSL Built-In Functions (§4.1) and
//! `[InitialValues]` Rule Grammar (§4.2).
//!
//! D1 Provenance:
//! - Independent reference values generated by `R 4.5.2 (2025-10-31)` via
//!   `crates/fit/tests/reference/r18_4_dsl_builtins.R`.
//! - Mathematical definitions: Abramowitz & Stegun (1964) §§6, 9.8, 26.5;
//!   NIST DLMF §§8.17, 10.25–10.35; Finney (1971) probit scale `5 + Phi^-1(p)`.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::excessive_precision)]

use curvebook_fit::{CompiledDslModel, DataPoint, DatasetSeries, FitStatus, HookContext, ParametricModel, SolverConfig, fit_nonlinear};
use curvebook_testkit::assert_approx_eq;

fn eval_dsl(expr: &str, x: &[f64]) -> Option<f64> {
    let model = CompiledDslModel::compile("r18_4_test", expr).expect("valid DSL expression");
    model.eval(x, &[], 0)
}

#[test]
fn d1_r18_4_incomplete_beta_and_gamma_oracles() {
    assert_approx_eq(eval_dsl("Y = ibeta(2.5, 3.5, 0.4)", &[0.0]).unwrap(), 4.869_041_915_261_175_8e-1, 1e-13, 1e-13, "ibeta(2.5,3.5,0.4)");
    assert_approx_eq(eval_dsl("Y = ibeta(0.5, 0.5, 0.25)", &[0.0]).unwrap(), 3.333_333_333_333_332_6e-1, 1e-13, 1e-13, "ibeta(0.5,0.5,0.25)");
    assert_approx_eq(eval_dsl("Y = ibeta(12.0, 8.0, 0.72)", &[0.0]).unwrap(), 8.662_193_673_584_953_6e-1, 1e-13, 1e-13, "ibeta(12,8,0.72)");

    assert_approx_eq(eval_dsl("Y = igamma(2.5, 1.8)", &[0.0]).unwrap(), 3.916_867_079_185_313_9e-1, 1e-13, 1e-13, "igamma(2.5,1.8)");
    assert_approx_eq(eval_dsl("Y = igammac(2.5, 1.8)", &[0.0]).unwrap(), 6.083_132_920_814_685_6e-1, 1e-13, 1e-13, "igammac(2.5,1.8)");
    assert_approx_eq(eval_dsl("Y = igamma(10.0, 15.0)", &[0.0]).unwrap(), 9.301_463_393_005_902_1e-1, 1e-13, 1e-13, "igamma(10,15)");
    assert_approx_eq(eval_dsl("Y = igammac(10.0, 15.0)", &[0.0]).unwrap(), 6.985_366_069_940_977_8e-2, 1e-13, 1e-13, "igammac(10,15)");

    // Domain rejections
    assert!(eval_dsl("Y = ibeta(0, 1, 0.5)", &[0.0]).is_none());
    assert!(eval_dsl("Y = ibeta(1, 1, -0.1)", &[0.0]).is_none());
    assert!(eval_dsl("Y = igamma(0, 1)", &[0.0]).is_none());
    assert!(eval_dsl("Y = igammac(2, -1)", &[0.0]).is_none());
}

#[test]
fn d1_r18_4_normal_student_t_f_chi2_binomial_oracles() {
    // Normal (standard + 3-arg + 1-arg backward compatibility)
    assert_approx_eq(eval_dsl("Y = zdist(-1.96)", &[0.0]).unwrap(), 2.499_789_514_822_042_8e-2, 1e-13, 1e-13, "zdist(-1.96)");
    assert_approx_eq(eval_dsl("Y = zdist(2.5)", &[0.0]).unwrap(), 9.937_903_346_742_238_4e-1, 1e-13, 1e-13, "zdist(2.5)");
    assert_approx_eq(eval_dsl("Y = normcdf(2.5)", &[0.0]).unwrap(), 9.937_903_346_742_238_4e-1, 1e-13, 1e-13, "normcdf(2.5)");
    assert_approx_eq(eval_dsl("Y = zinv(0.975)", &[0.0]).unwrap(), 1.959_963_984_540_053_4, 1e-12, 1e-12, "zinv(0.975)");
    assert_approx_eq(eval_dsl("Y = norminv(0.975)", &[0.0]).unwrap(), 1.959_963_984_540_053_4, 1e-12, 1e-12, "norminv(0.975) 1-arg");
    assert_approx_eq(eval_dsl("Y = zinv(1e-6)", &[0.0]).unwrap(), -4.753_424_308_822_898_7, 1e-11, 1e-11, "zinv(1e-6)");
    assert_approx_eq(eval_dsl("Y = zpdf(1.5)", &[0.0]).unwrap(), 1.295_175_956_658_917_4e-1, 1e-14, 1e-14, "zpdf(1.5)");

    assert_approx_eq(eval_dsl("Y = normdist(115, 100, 15)", &[0.0]).unwrap(), 8.413_447_460_685_429_3e-1, 1e-13, 1e-13, "normdist");
    assert_approx_eq(eval_dsl("Y = norminv(0.9, 100, 15)", &[0.0]).unwrap(), 1.192_232_734_831_690_1e2, 1e-11, 1e-11, "norminv 3-arg");
    assert_approx_eq(eval_dsl("Y = normpdf(115, 100, 15)", &[0.0]).unwrap(), 1.613_138_163_460_955_6e-2, 1e-14, 1e-14, "normpdf");
    assert!(eval_dsl("Y = normdist(115, 100, 0)", &[0.0]).is_none());
    assert!(eval_dsl("Y = norminv(0.5, 100, -1)", &[0.0]).is_none());
    assert!(eval_dsl("Y = normpdf(115, 100, -2)", &[0.0]).is_none());
    assert!(CompiledDslModel::compile("bad_norminv_arity", "Y = norminv(0.5, 100)").is_err());

    // Student t
    assert_approx_eq(eval_dsl("Y = tdist(2.22813885, 10)", &[0.0]).unwrap(), 2.500_000_008_418_819_3e-2, 1e-12, 1e-12, "tdist(2.228,10)");
    assert_approx_eq(eval_dsl("Y = tdist(-1.5, 7.5)", &[0.0]).unwrap(), 9.127_597_147_067_679_8e-1, 1e-12, 1e-12, "tdist(-1.5,7.5)");
    assert_approx_eq(eval_dsl("Y = tinv(0.05, 10)", &[0.0]).unwrap(), 2.228_138_851_986_273_5, 1e-10, 1e-10, "tinv(0.05,10)");
    assert_approx_eq(eval_dsl("Y = tinv(0.01, 25)", &[0.0]).unwrap(), 2.787_435_813_676_970_6, 1e-10, 1e-10, "tinv(0.01,25)");
    assert_approx_eq(eval_dsl("Y = tpdf(1.25, 8)", &[0.0]).unwrap(), 1.732_632_662_836_461_9e-1, 1e-13, 1e-13, "tpdf(1.25,8)");
    assert!(eval_dsl("Y = tdist(1.0, 0)", &[0.0]).is_none());
    assert!(eval_dsl("Y = tinv(0, 10)", &[0.0]).is_none());

    // Snedecor F
    assert_approx_eq(eval_dsl("Y = fdist(3.5, 4, 20)", &[0.0]).unwrap(), 2.538_523_086_644_129_5e-2, 1e-12, 1e-12, "fdist(3.5,4,20)");
    assert_approx_eq(eval_dsl("Y = finv(0.05, 4, 20)", &[0.0]).unwrap(), 2.866_081_402_015_658_9, 1e-10, 1e-10, "finv(0.05,4,20)");
    assert_approx_eq(eval_dsl("Y = finv(0.01, 2, 15)", &[0.0]).unwrap(), 6.358_873_480_667_181_6, 1e-10, 1e-10, "finv(0.01,2,15)");
    assert_approx_eq(eval_dsl("Y = fpdf(2.4, 5, 12)", &[0.0]).unwrap(), 1.012_535_888_625_717_4e-1, 1e-13, 1e-13, "fpdf(2.4,5,12)");
    assert!(eval_dsl("Y = fdist(-1, 4, 20)", &[0.0]).is_none());
    assert!(eval_dsl("Y = finv(0, 4, 20)", &[0.0]).is_none());

    // Chi-square
    assert_approx_eq(eval_dsl("Y = chidist(9.487729, 4)", &[0.0]).unwrap(), 5.000_000_075_944_004_8e-2, 1e-12, 1e-12, "chidist");
    assert_approx_eq(eval_dsl("Y = chisqc(9.487729, 4)", &[0.0]).unwrap(), 9.499_999_992_405_600_0e-1, 1e-12, 1e-12, "chisqc");
    assert_approx_eq(eval_dsl("Y = chiinv(0.05, 4)", &[0.0]).unwrap(), 9.487_729_036_781_154, 1e-10, 1e-10, "chiinv(0.05,4)");
    assert_approx_eq(eval_dsl("Y = chiinv(0.01, 12)", &[0.0]).unwrap(), 2.621_696_730_553_585_7e1, 1e-10, 1e-10, "chiinv(0.01,12)");
    assert!(eval_dsl("Y = chidist(-1, 4)", &[0.0]).is_none());
    assert!(eval_dsl("Y = chiinv(0, 4)", &[0.0]).is_none());

    // Binomial upper cumulative tail
    assert_approx_eq(eval_dsl("Y = binomial(3, 10, 0.25)", &[0.0]).unwrap(), 4.744_071_960_449_222_1e-1, 1e-13, 1e-13, "binomial(3,10,0.25)");
    assert_approx_eq(eval_dsl("Y = binomial(2.3, 10, 0.25)", &[0.0]).unwrap(), 4.744_071_960_449_222_1e-1, 1e-13, 1e-13, "binomial(2.3,10,0.25)");
    assert_approx_eq(eval_dsl("Y = binomial(15, 25, 0.4)", &[0.0]).unwrap(), 3.439_151_809_067_862_0e-2, 1e-13, 1e-13, "binomial(15,25,0.4)");
    assert_approx_eq(eval_dsl("Y = binomial(0, 10, 0.3)", &[0.0]).unwrap(), 1.0, 1e-15, 1e-15, "binomial(0,10,0.3)");
    assert_approx_eq(eval_dsl("Y = binomial(11, 10, 0.3)", &[0.0]).unwrap(), 0.0, 1e-15, 1e-15, "binomial(11,10,0.3)");
    assert!(eval_dsl("Y = binomial(2, 10.5, 0.3)", &[0.0]).is_none());
    assert!(eval_dsl("Y = binomial(2, 10, 1.2)", &[0.0]).is_none());
}

#[test]
fn d1_r18_4_helpers_bessel_and_aliases_oracles() {
    // Algebraic helpers
    assert_approx_eq(eval_dsl("Y = fact(0)", &[0.0]).unwrap(), 1.0, 1e-15, 1e-15, "fact(0)");
    assert_approx_eq(eval_dsl("Y = fact(12)", &[0.0]).unwrap(), 4.790_016_000_000_000e8, 1e-12, 1e-12, "fact(12)");
    assert_approx_eq(eval_dsl("Y = fact(100)", &[0.0]).unwrap(), 9.332_621_544_394_224_9e157, 1e-12, 1e-12, "fact(100)");
    assert!(eval_dsl("Y = fact(-1)", &[0.0]).is_none());
    assert!(eval_dsl("Y = fact(2.5)", &[0.0]).is_none());
    assert!(eval_dsl("Y = fact(171)", &[0.0]).is_none());

    assert_approx_eq(eval_dsl("Y = logit(0.2)", &[0.0]).unwrap(), -1.386_294_361_119_890_6, 1e-14, 1e-14, "logit(0.2)");
    assert_approx_eq(eval_dsl("Y = logit(0.999)", &[0.0]).unwrap(), 6.906_754_778_648_553, 1e-12, 1e-12, "logit(0.999)");
    assert!(eval_dsl("Y = logit(0)", &[0.0]).is_none());
    assert!(eval_dsl("Y = logit(1)", &[0.0]).is_none());

    assert_approx_eq(eval_dsl("Y = probit(0.5)", &[0.0]).unwrap(), 5.0, 1e-14, 1e-14, "probit(0.5)");
    assert_approx_eq(eval_dsl("Y = probit(0.975)", &[0.0]).unwrap(), 6.959_963_984_540_053, 1e-12, 1e-12, "probit(0.975)");
    assert_approx_eq(eval_dsl("Y = probit(0.1)", &[0.0]).unwrap(), 3.718_448_434_455_399_2, 1e-12, 1e-12, "probit(0.1)");
    assert!(eval_dsl("Y = probit(0)", &[0.0]).is_none());
    assert!(eval_dsl("Y = probit(1)", &[0.0]).is_none());

    assert_approx_eq(eval_dsl("Y = perc(37.5)", &[0.0]).unwrap(), 0.375, 1e-15, 1e-15, "perc");
    assert_approx_eq(eval_dsl("Y = deg(PI / 2)", &[0.0]).unwrap(), 90.0, 1e-13, 1e-13, "deg");
    assert_approx_eq(eval_dsl("Y = rad(180)", &[0.0]).unwrap(), std::f64::consts::PI, 1e-14, 1e-14, "rad");
    assert_approx_eq(eval_dsl("Y = sqr(-3.5)", &[0.0]).unwrap(), 12.25, 1e-15, 1e-15, "sqr");
    assert_approx_eq(eval_dsl("Y = int(-3.9)", &[0.0]).unwrap(), -3.0, 1e-15, 1e-15, "int(-3.9)");
    assert_approx_eq(eval_dsl("Y = int(3.9)", &[0.0]).unwrap(), 3.0, 1e-15, 1e-15, "int(3.9)");
    assert_approx_eq(eval_dsl("Y = sgn(-4.2)", &[0.0]).unwrap(), -1.0, 1e-15, 1e-15, "sgn");
    assert_approx_eq(eval_dsl("Y = mod(17.5, 5)", &[0.0]).unwrap(), 2.5, 1e-15, 1e-15, "mod(17.5,5)");
    assert_approx_eq(eval_dsl("Y = X mod 5", &[17.5]).unwrap(), 2.5, 1e-15, 1e-15, "infix mod");
    assert!(eval_dsl("Y = mod(5, 0)", &[0.0]).is_none());

    // is_defined(x) for multivariable rows (including NaN / Inf short-circuiting)
    let mv = CompiledDslModel::compile("mv_is_def", "Y = IF(is_defined(X2), 2 * X1 + 3 * X2, 2 * X1)").unwrap();
    assert_eq!(mv.param_names(), &[] as &[String]);
    assert_approx_eq(mv.eval(&[4.0, 5.0], &[], 0).unwrap(), 23.0, 1e-15, 1e-15, "is_defined finite");
    assert_approx_eq(mv.eval(&[4.0, f64::NAN], &[], 0).unwrap(), 8.0, 1e-15, 1e-15, "is_defined NaN");
    assert_approx_eq(mv.eval(&[4.0, f64::INFINITY], &[], 0).unwrap(), 8.0, 1e-15, 1e-15, "is_defined Inf");

    // General integer-order modified Bessel I_n and K_n
    assert_approx_eq(eval_dsl("Y = besseli(0, 2.5)", &[0.0]).unwrap(), 3.289_839_144_050_122_7, 1e-12, 1e-12, "besseli(0,2.5)");
    assert_approx_eq(eval_dsl("Y = besseli(1, 2.5)", &[0.0]).unwrap(), 2.516_716_245_288_698_4, 1e-12, 1e-12, "besseli(1,2.5)");
    assert_approx_eq(eval_dsl("Y = besseli(3, 2.5)", &[0.0]).unwrap(), 4.743_704_087_780_355_5e-1, 1e-12, 1e-12, "besseli(3,2.5)");
    assert_approx_eq(eval_dsl("Y = besseli(-3, 2.5)", &[0.0]).unwrap(), 4.743_704_087_780_355_5e-1, 1e-12, 1e-12, "besseli(-3,2.5)");
    assert_approx_eq(eval_dsl("Y = besseli(3, -2.5)", &[0.0]).unwrap(), -4.743_704_087_780_355_5e-1, 1e-12, 1e-12, "besseli(3,-2.5)");
    assert_approx_eq(eval_dsl("Y = besseli(4, -2.5)", &[0.0]).unwrap(), 1.379_771_667_518_788_5e-1, 1e-12, 1e-12, "besseli(4,-2.5)");
    assert_approx_eq(eval_dsl("Y = besseli(5, 30.0)", &[0.0]).unwrap(), 5.121_514_654_769_350e11, 1e-11, 1e-11, "besseli(5,30)");
    assert_approx_eq(eval_dsl("Y = besseli(10, 40.0)", &[0.0]).unwrap(), 4.228_469_210_516_758_5e15, 1e-11, 1e-11, "besseli(10,40)");
    assert_approx_eq(eval_dsl("Y = besseli(0, 0)", &[0.0]).unwrap(), 1.0, 1e-15, 1e-15, "besseli(0,0)");
    assert_approx_eq(eval_dsl("Y = besseli(3, 0)", &[0.0]).unwrap(), 0.0, 1e-15, 1e-15, "besseli(3,0)");

    // K_0/K_1 use A&S 9.8.5–9.8.8 (~1e-7 accuracy), inherited by upward recurrence for K_n.
    assert_approx_eq(eval_dsl("Y = besselk(0, 1.5)", &[0.0]).unwrap(), 2.138_055_626_475_257_3e-1, 1e-6, 1e-6, "besselk(0,1.5)");
    assert_approx_eq(eval_dsl("Y = besselk(1, 1.5)", &[0.0]).unwrap(), 2.773_878_004_568_438_0e-1, 1e-6, 1e-6, "besselk(1,1.5)");
    assert_approx_eq(eval_dsl("Y = besselk(3, 1.5)", &[0.0]).unwrap(), 1.833_803_702_474_579_2, 1e-6, 1e-6, "besselk(3,1.5)");
    assert_approx_eq(eval_dsl("Y = besselk(-3, 1.5)", &[0.0]).unwrap(), 1.833_803_702_474_579_2, 1e-6, 1e-6, "besselk(-3,1.5)");
    assert_approx_eq(eval_dsl("Y = besselk(5, 4.0)", &[0.0]).unwrap(), 1.543_425_487_259_971_2e-1, 1e-6, 1e-6, "besselk(5,4)");
    assert!(eval_dsl("Y = besselk(2, 0)", &[0.0]).is_none());
    assert!(eval_dsl("Y = besselk(2, -1)", &[0.0]).is_none());
    assert!(eval_dsl("Y = besseli(100001, 2.0)", &[0.0]).is_none());
    assert!(eval_dsl("Y = besselk(100001, 2.0)", &[0.0]).is_none());

    // Canonical special-function aliases
    assert_approx_eq(
        eval_dsl("Y = gammaln(5.5)", &[0.0]).unwrap(),
        eval_dsl("Y = lngamma(5.5)", &[0.0]).unwrap(),
        1e-15,
        1e-15,
        "gammaln == lngamma",
    );
    assert_approx_eq(
        eval_dsl("Y = hypgeometricm(1.5, 2.5, 1.2)", &[0.0]).unwrap(),
        eval_dsl("Y = hyp1f1(1.5, 2.5, 1.2)", &[0.0]).unwrap(),
        1e-15,
        1e-15,
        "hypgeometricm == hyp1f1",
    );
    assert_approx_eq(
        eval_dsl("Y = hypgeometricu(1.5, 2.5, 1.2)", &[0.0]).unwrap(),
        eval_dsl("Y = confluent_u(1.5, 2.5, 1.2)", &[0.0]).unwrap(),
        1e-15,
        1e-15,
        "hypgeometricu == confluent_u",
    );
    assert_approx_eq(
        eval_dsl("Y = hypgeometricf(0.5, 1.5, 2.5, 0.3)", &[0.0]).unwrap(),
        eval_dsl("Y = hyp2f1(0.5, 1.5, 2.5, 0.3)", &[0.0]).unwrap(),
        1e-15,
        1e-15,
        "hypgeometricf == hyp2f1",
    );
}

#[test]
fn d1_r18_4_initial_values_rule_grammar_anchors_and_titles() {
    let src = r"
[Equation]
Y = P0 + P1 * X + P2 + P3 + P4 + P5 + P6 + P7 + P8 + P9 + P10
[InitialValues]
P0 = 4.5 * (InitialValue)
P1 = 2 * YMIN
P2 = 0.5 * YMAX
P3 = 1 * YMID
P4 = 1 * XatYmid
P5 = 1 * YatXmin
P6 = 1 * YatXmid
P7 = 1 * YatXmax
P8 = SIGN(YatXmax - YatXmin)
P9 = 2 * MeanColumnTitle
P10 = 1 * LogMeanColumnTitle
";
    let model = CompiledDslModel::compile("init_anchors", src).expect("compile init_anchors");

    // Monotonically decreasing linear data y = 20 - 2*x on x in [0, 10] with replicate at x=0
    let pts = vec![DataPoint::xy(0.0, 19.0), DataPoint::xy(0.0, 21.0), DataPoint::xy(2.0, 16.0), DataPoint::xy(6.0, 8.0), DataPoint::xy(10.0, 0.0)];
    let titles = [10.0, 100.0, 190.0]; // mean = 100.0, log10(mean) = 2.0
    let init = model.initial_guess_with_column_titles(&pts, &titles);
    assert_approx_eq(init[0], 4.5, 1e-14, 1e-14, "c * (InitialValue)");
    assert_approx_eq(init[1], 0.0, 1e-14, 1e-14, "2 * YMIN");
    assert_approx_eq(init[2], 10.5, 1e-14, 1e-14, "0.5 * YMAX");
    assert_approx_eq(init[3], 10.5, 1e-14, 1e-14, "YMID");
    assert_approx_eq(init[4], 4.75, 1e-12, 1e-12, "XatYmid");
    assert_approx_eq(init[5], 20.0, 1e-14, 1e-14, "YatXmin (replicate mean)");
    assert_approx_eq(init[6], 10.0, 1e-14, 1e-14, "YatXmid (interpolated at x=5)");
    assert_approx_eq(init[7], 0.0, 1e-14, 1e-14, "YatXmax");
    assert_approx_eq(init[8], -1.0, 1e-14, 1e-14, "SIGN(YatXmax - YatXmin) decreasing");
    assert_approx_eq(init[9], 200.0, 1e-14, 1e-14, "2 * MeanColumnTitle");
    assert_approx_eq(init[10], 2.0, 1e-14, 1e-14, "LogMeanColumnTitle");

    // Verify with_column_title_values forwards through ParametricModel::initial_guess
    let bound = model.clone().with_column_title_values(titles.to_vec());
    let via_trait = bound.initial_guess(&pts);
    assert_approx_eq(via_trait[9], 200.0, 1e-14, 1e-14, "bound MeanColumnTitle");
    assert_approx_eq(via_trait[10], 2.0, 1e-14, 1e-14, "bound LogMeanColumnTitle");

    // Missing column titles fall back cleanly to default guess (1.0) without NaN/panic
    let no_titles = model.initial_guess(&pts);
    assert_approx_eq(no_titles[9], 1.0, 1e-14, 1e-14, "fallback MeanColumnTitle");
    assert_approx_eq(no_titles[10], 1.0, 1e-14, 1e-14, "fallback LogMeanColumnTitle");
}

#[test]
fn d1_r18_4_initial_values_empirical_slopes_oracles() {
    let src = r"
[Equation]
Y = SMin * X + SMid + SMax + RMin + RMid + RMax
[InitialValues]
SMin = 1 * SlopeAtXmin
SMid = 1 * SlopeAtXmid
SMax = 1 * SlopeAtXmax
RMin = 2 / SlopeAtXmin
RMid = 2 / SlopeAtXmid
RMax = 2 / SlopeAtXmax
";
    let model = CompiledDslModel::compile("init_slopes", src).expect("compile init_slopes");

    // Case 1: N = 40 >= 30, k = floor(0.10 * 40) = 4, y = 0.05 * x^2 - 1.2 * x + 3
    let pts40: Vec<DataPoint> = (0..40)
        .rev() // deliberately unsorted to verify sorting before windowing
        .map(|i| {
            let x = f64::from(i);
            DataPoint::xy(x, 0.05 * x * x - 1.2 * x + 3.0)
        })
        .collect();
    let init40 = model.initial_guess(&pts40);
    assert_approx_eq(init40[0], -1.05, 1e-13, 1e-13, "slope_xmin_n40");
    assert_approx_eq(init40[1], 0.75, 1e-13, 1e-13, "slope_xmid_n40");
    assert_approx_eq(init40[2], 2.55, 1e-13, 1e-13, "slope_xmax_n40");
    assert_approx_eq(init40[3], 2.0 / -1.05, 1e-13, 1e-13, "recip slope_xmin_n40");
    assert_approx_eq(init40[4], 2.0 / 0.75, 1e-13, 1e-13, "recip slope_xmid_n40");
    assert_approx_eq(init40[5], 2.0 / 2.55, 1e-13, 1e-13, "recip slope_xmax_n40");

    // Case 2: N = 7 < 30 (odd: 3-point central OLS), y = x^2
    let pts7: Vec<DataPoint> = [0.0, 1.0, 2.0, 3.0, 5.0, 7.0, 10.0].into_iter().map(|x| DataPoint::xy(x, x * x)).collect();
    let init7 = model.initial_guess(&pts7);
    assert_approx_eq(init7[0], 1.0, 1e-13, 1e-13, "slope_xmin_n7");
    assert_approx_eq(init7[1], 7.142_857_142_857_146, 1e-12, 1e-12, "slope_xmid_n7 (3-pt OLS)");
    assert_approx_eq(init7[2], 17.0, 1e-13, 1e-13, "slope_xmax_n7");

    // Case 3: N = 6 < 30 (even: 2-point central secant), y = x^2
    let pts6: Vec<DataPoint> = [0.0, 1.0, 2.0, 4.0, 7.0, 10.0].into_iter().map(|x| DataPoint::xy(x, x * x)).collect();
    let init6 = model.initial_guess(&pts6);
    assert_approx_eq(init6[0], 1.0, 1e-13, 1e-13, "slope_xmin_n6");
    assert_approx_eq(init6[1], 6.0, 1e-13, 1e-13, "slope_xmid_n6 (2-pt secant)");
    assert_approx_eq(init6[2], 17.0, 1e-13, 1e-13, "slope_xmax_n6");
}

#[test]
fn d1_r18_4_end_to_end_custom_fit_with_new_builtins_and_init_rules() {
    // Fit a cumulative normal dose-response model using 3-arg normdist + §4.2 [InitialValues] rules.
    let src = r"
[Equation]
Y = Bottom + (Top - Bottom) * normdist(X, Mu, Sigma)
[InitialValues]
Bottom = 1 * YatXmin
Top = 1 * YatXmax
Mu = 1 * XatYmid
Sigma = 0.25 * (XMAX - XMIN)
";
    let model = CompiledDslModel::compile("cum_norm_fit", src).expect("compile cum_norm_fit");
    let true_params = [10.0, 90.0, 5.0, 1.5]; // Bottom, Top, Mu, Sigma
    let points: Vec<DataPoint> = (0..25)
        .map(|i| {
            let x = 0.5 * f64::from(i);
            let y = model.eval(&[x], &true_params, 0).expect("model eval");
            DataPoint::xy(x, y)
        })
        .collect();
    let series = DatasetSeries {
        data_set_index: 0,
        label: "CumulativeNormal".to_owned(),
        points,
        unknowns_y: Vec::new(),
        unknowns_x: Vec::new(),
        is_pre_summarized: false,
        column_title_value: None,
    };
    let res = fit_nonlinear(&model, &[series], &HookContext::default(), &SolverConfig::default()).expect("fit succeeds");
    assert_eq!(res.status, FitStatus::Converged);
    for ((&val, name), &truth) in res.datasets[0].params.iter().zip(&res.datasets[0].param_names).zip(&true_params) {
        assert_approx_eq(val, truth, 1e-6, 1e-6, name);
    }
}
